import json,subprocess
from concurrent.futures import ThreadPoolExecutor
commands=[['hpc','quota'],['hpc','help'],['quota','-s']]
def run(cmd):
 try:
  r=subprocess.run(cmd,text=True,capture_output=True,timeout=20)
  return {'command':cmd,'exit_code':r.returncode,'stdout':r.stdout,'stderr':r.stderr}
 except (subprocess.TimeoutExpired,OSError) as e:return {'command':cmd,'error':str(e)}
for row in ThreadPoolExecutor(max_workers=3).map(run,commands):print(json.dumps(row),flush=True)

